"""Observed vs. exact Born weights for a superposition with a hidden branch."""
from __future__ import annotations
from typing import List, Tuple

ORDER = 12

def mul(a: Tuple[float, ...], b: Tuple[float, ...]) -> Tuple[float, ...]:
    out = [0.0] * ORDER
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if i + j < ORDER:
                    out[i + j] += x * y
    return tuple(out)

def add(a: Tuple[float, ...], b: Tuple[float, ...]) -> Tuple[float, ...]:
    return tuple(x + y for x, y in zip(a, b))

def const(x: float) -> Tuple[float, ...]:
    c = [0.0] * ORDER; c[0] = x; return tuple(c)

def inverse(a: Tuple[float, ...]) -> Tuple[float, ...]:
    a0 = a[0]
    u = tuple((c / a0) if i else 0.0 for i, c in enumerate(a))
    res, term = const(1.0), const(1.0)
    negu = tuple(-c for c in u)
    for _ in range(ORDER - 1):
        term = mul(term, negu); res = add(res, term)
    return mul(res, const(1.0 / a0))

def observed(amps: List[Tuple[float, ...]]) -> List[float]:
    z = const(0.0)
    for a in amps:
        z = add(z, mul(a, a))
    zi = inverse(z)
    return [mul(mul(a, a), zi)[0] for a in amps]

if __name__ == "__main__":
    eps = tuple(1.0 if i == 1 else 0.0 for i in range(ORDER))
    amps = [const(2.0 ** -0.5), const(2.0 ** -0.5), mul(const(2.0 ** -0.5), eps)]
    print("observed probabilities:", [round(p, 12) for p in observed(amps)])
    print("sum:", round(sum(observed(amps)), 12))

"""Lexicographic probability collapse to the primary layer via the standard part."""
from __future__ import annotations
from typing import List, Sequence

ORDER = 8

def encode(vec: Sequence[float]) -> List[float]:
    c = [0.0] * ORDER
    for i, v in enumerate(vec):
        if i < ORDER:
            c[i] = v
    return c

def add(a: List[float], b: List[float]) -> List[float]:
    return [x + y for x, y in zip(a, b)]

def scale(a: List[float], s: float) -> List[float]:
    return [x * s for x in a]

def observed(vectors: Sequence[Sequence[float]]) -> List[float]:
    q = [encode(v) for v in vectors]
    z = [0.0] * ORDER
    for e in q:
        z = add(z, e)
    inv0 = 1.0 / z[0]          # z is appreciable: leading term is the total primary mass
    return [e[0] * inv0 for e in q]

if __name__ == "__main__":
    vectors = [[0.5, 0.0, 0.3], [0.5, 0.0, 0.2], [0.0, 1.0, 0.5]]
    print("observed distribution:", [round(p, 12) for p in observed(vectors)])

"""Visibility level of a branch: the epsilon-valuation of its Born weight."""
from __future__ import annotations
from typing import List, Tuple

ORDER = 16

def mul(a: Tuple[float, ...], b: Tuple[float, ...]) -> Tuple[float, ...]:
    out = [0.0] * ORDER
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if i + j < ORDER:
                    out[i + j] += x * y
    return tuple(out)

def valuation(a: Tuple[float, ...], tol: float = 1e-12) -> int:
